import requests, os, sys
DIR_NAME = os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))))))
sys.path.append(DIR_NAME)
from apis.function_layer.base_functions import BaseFunction
from datetime import datetime, timedelta

class Handicap(BaseFunction):
   # 期数管理-取得盤口的期數列表
   def get_record(self, handicap, certification, url):
      # 期数管理-取得盤口的期數列表
      url = f'{url}apis/lottery/{handicap}/record?status=-1&payout=-1&pi=1'

      record_res = self.get(url, certification=certification)
      assert record_res.status_code == 200, f'api狀態碼不正確: {record_res.status_code}'

      return record_res

   # 期数管理-取得最新封盤的期數資料
   def get_last_block_record_info(self, record_list):

      res = {}
      opentime = ''
      closetime = ''
      drawingtime = ''

      for record in record_list.json()['Items']:
         if record['status'] == 2:
            opentime = record['opentime']
            closetime = record['closetime']
            drawingtime = record['drawingtime']
            res['hm1'] = str(record['hm1'])
            res['hm2'] = str(record['hm2'])
            res['hm3'] = str(record['hm3'])
            res['hm4'] = str(record['hm4'])
            res['hm5'] = str(record['hm5'])
            res['hm6'] = str(record['hm6'])
            res['hm7'] = str(record['hm7'])
            break
      
      assert res != {}, '無法取得最新封盤的期數資料'

      dt_opentime = datetime.strptime(opentime, '%Y-%m-%d %H:%M:%S') + timedelta(hours=12)
      dt_closetime = datetime.strptime(closetime, '%Y-%m-%d %H:%M:%S') + timedelta(hours=12)
      dt_drawingtime = datetime.strptime(drawingtime, '%Y-%m-%d %H:%M:%S') + timedelta(hours=12)
      str_opentime = dt_opentime.strftime('%Y-%m-%d %H:%M:%S')
      str_closetime = dt_closetime.strftime('%Y-%m-%d %H:%M:%S')
      str_drawingtime = dt_drawingtime.strftime('%Y-%m-%d %H:%M:%S')

      res['opentime'] = str_opentime
      res['closetime'] = str_closetime
      res['drawingtime'] = str_drawingtime

      return res

   # 期数管理-新增期數
   def add_period(self, handicap, period, record_info, certification, url):

      url = f'{url}apis/lottery/{handicap}/record'

      payload = {
         'number': period,
         'opentime': record_info['opentime'],
         'closetime': record_info['closetime'],
         'drawingtime': record_info['drawingtime']
      }

      add_period_res = self.post(url, data=payload, certification=certification)
      assert add_period_res.status_code == 200, f'api狀態碼不正確: {add_period_res.status_code}'
      assert '已新增' in add_period_res.text, f'期數: {period} 新增失敗'

   # 期数管理-更新期數內容
   def push_period(self, handicap, period, record_info, certification, url):

      url = f'{url}apis/lottery/{handicap}/record/{period}'

      payload= {
         'number': period,
         'opentime': record_info['opentime'],
         'closetime': record_info['closetime'],
         'drawingtime': record_info['drawingtime'],
         'hm1': '1',
         'hm2': '2',
         'hm3': '3',
         'hm4': '4',
         'hm5': '5',
         'hm6': '6',
         'hm7': '7',
         'result': '1234567'
      }

      push_period_res = self.put(url, data=payload, certification=certification)
      assert push_period_res.status_code == 200, f'api狀態碼不正確: {push_period_res.status_code}'
      assert '已修改' in push_period_res.text, f'期數: {period} 修改失敗'

   # 期数管理-派彩狀態-重派
   def payout(self, handicap, period, record_info, repayout, certification, url):

      url = f'{url}apis/lottery/{handicap}/record/{period}/payout'
      result = record_info['hm1'] + record_info['hm2'] + record_info['hm3'] + record_info['hm4'] + record_info['hm5'] + record_info['hm6'] + record_info['hm7']

      payload= {
         'number': period,
         'opentime': record_info['opentime'],
         'closetime': record_info['closetime'],
         'drawingtime': record_info['drawingtime'],
         'hm1': record_info['hm1'],
         'hm2': record_info['hm2'],
         'hm3': record_info['hm3'],
         'hm4': record_info['hm4'],
         'hm5': record_info['hm5'],
         'hm6': record_info['hm6'],
         'hm7': record_info['hm7'],
         'result': result,
         'payoutcount': '0',
         'nopayoutcount': '0'
      }

      if repayout == True:
         repayout_res = self.put(url, data=payload, certification=certification)
      else:
         repayout_res = self.post(url, data=payload, certification=certification)
      assert repayout_res.status_code == 200, f'api狀態碼不正確: {repayout_res.status_code}'

      if repayout == True:
         assert '已提交，请稍后查询结果' in repayout_res.text, f'期數: {period} 重派失敗'
      else:
         assert '已提交，请稍后查询结果' in repayout_res.text, f'期數: {period} 派彩失敗'

   # 期数管理-開盤/封盤
   def change_handicap_status(self, handicap, period, open, certification, url):

      url = f'{url}apis/lottery/{handicap}/record/{period}/status'

      if open == True:
         open_handicap_res = self.post(url, certification=certification)
      else:
         open_handicap_res = self.delete(url, certification=certification)
      assert open_handicap_res.status_code == 200, f'api狀態碼不正確: {open_handicap_res.status_code}'

      if open ==True:
         assert '已开盘' in open_handicap_res.text, f'期數: {period} 開盤失敗'
      else:
         assert '已封盘' in open_handicap_res.text, f'期數: {period} 封盤失敗'

   # 期数管理-作廢
   def rescind_period(self, handicap, period, certification, url):

      url = f'{url}apis/lottery/{handicap}/record/{period}/order'

      rescind_period_res = self.delete(url, certification=certification)
      assert rescind_period_res.status_code == 200, f'api狀態碼不正確: {rescind_period_res.status_code}'
      assert '已提交，请稍后查询结果' in rescind_period_res.text, f'期數: {period} 作廢失敗'

   # 期数管理-補彩
   def makeup_payout(self, handicap, period, record_info, certification, url):

      url = f'{url}apis/lottery/{handicap}/record/{period}/draw'

      makeup_payout_res = self.put(url, certification=certification)

      assert makeup_payout_res.status_code == 200, f'api狀態碼不正確: {makeup_payout_res.status_code}'
      assert makeup_payout_res.json()['number'] == period and makeup_payout_res.json()['drawingtime'] == record_info['drawingtime'], f"response內容不正確: drawingtime: {makeup_payout_res.json()['drawingtime']} / data_drawingtime: {record_info['drawingtime']}，period: {makeup_payout_res.json()['number']} / data_period: {period}"

   # 期数管理-刪除
   def del_period(self, handicap, period, certification, url):

      url = f'{url}apis/lottery/{handicap}/record/{period}'

      del_period_res = self.delete(url, certification=certification)
      assert del_period_res.status_code == 200, f'api狀態碼不正確: {del_period_res.status_code}'
      assert '已删除' in del_period_res.text, f'期數: {period} 刪除失敗'

   # 盘口管理-新增盤口
   def add_handicap(self, handicap, handicap_id, certification, url):

      url = f'{url}apis/lottery/{handicap}/room'

      payload = {
         'code': 'bot',
         'name': 'bot_test',
         'status': '1',
         'maxamount': '10000',
         'minamount': '1',
         'maxwin': '1',
         'sort': '0'
      }

      add_handicap_res = self.post(url, data=payload, certification=certification)
      assert add_handicap_res.status_code == 200, f'api狀態碼不正確: {add_handicap_res.status_code} {add_handicap_res.text}'
      assert '已新增' in add_handicap_res.text, f'盤口: {handicap_id} 沒顯示已新增'

