   # 修改賠率
   def change_rate(self, handicap, handicap_id, certification, url):

      change_rate_res = self.change_rate_api(handicap, handicap_id, certification, url)
      assert change_rate_res.status_code == 200, f'api狀態碼不正確: {change_rate_res.status_code}'
      assert '已修改' in change_rate_res.text, f'盤口: {handicap_id} 賠率修改失敗'

   # 盘口管理-刪除盤口
   def del_handicap(self, handicap_info, handicap, certification, admin_url, status=''):
      handicap_id = 'bot'

      find = False
      for item in handicap_info.json()['Items']:
         if item['code'] == handicap_id:
            find = True

            url = f'{admin_url}apis/lottery/{handicap}/room/{handicap_id}'

            del_handicap_res = self.delete(url, certification=certification)
            assert del_handicap_res.status_code == 200, f'api狀態碼不正確: {del_handicap_res.status_code}'
            assert '已删除' in del_handicap_res.text, f'盤口: {handicap_id} 刪除失敗'
            break
      
      if status != 'default':
         assert find == True, '找不到指定盤口'

   # 盘口管理-取得盤口列表資訊
   def get_handicap_info(self, handicap, certification, url):

      url = f'{url}apis/lottery/{handicap}/room?pi=1'

      get_handicap_info_res = self.get(url, certification=certification)
      assert get_handicap_info_res.status_code == 200, f'api狀態碼不正確: {get_handicap_info_res.status_code}'

      return get_handicap_info_res

   # 盘口管理-修改盤口內容
   def change_handicap_info(self, handicap, handicap_id, certification, url):

      url = f'{url}apis/lottery/{handicap}/room/{handicap_id}'

      payload = {
         'code': handicap_id,
         'name': 'bot_test_new',
         'status': '0',
         'maxamount': '20000',
         'minamount': '2',
         'maxwin': '2',
         'sort': '1'
      }

      change_handicap_info_res = self.put(url, data=payload, certification=certification)
      assert change_handicap_info_res.status_code == 200, f'api狀態碼不正確: {change_handicap_info_res.status_code}'
      assert '已修改' in change_handicap_info_res.text, f'盤口: {handicap_id} 內容修改失敗'